CREATE TABLE datasets_next (
  key TEXT PRIMARY KEY CHECK (key IN ('kadra', 'wywiadowki', 'kontakty', 'dokumenty', 'partnerzy', 'oferty-pracy', 'kierunki', 'nawigacja')),
  data_json TEXT NOT NULL CHECK (json_valid(data_json)),
  updated_at TEXT NOT NULL
);

INSERT INTO datasets_next (key, data_json, updated_at)
SELECT key, data_json, updated_at FROM datasets;

DROP TABLE datasets;

ALTER TABLE datasets_next RENAME TO datasets;

